insert into public.preguntas
  (id, dominio, tema, dificultad, enunciado, opcion_a, opcion_b, opcion_c, opcion_d, correcta, explicacion)
values
(1, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Conceptos básicos', 'Básica', '¿Cuál de las siguientes opciones describe mejor un proyecto?', 'Un esfuerzo temporal que se lleva a cabo para crear un producto, servicio o resultado único.', 'Un grupo de programas gestionados para alcanzar objetivos estratégicos.', 'Un conjunto de procesos permanentes que sostienen el negocio.', 'Una operación continua que produce bienes de forma repetitiva.', 'A', 'Un proyecto es temporal (tiene inicio y fin) y su resultado es único.'),
(2, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Conceptos básicos', 'Básica', 'Una fábrica produce 500 unidades diarias del mismo producto y además planea implementar un nuevo sistema ERP. ¿Cuál de estas actividades es un proyecto?', 'El mantenimiento rutinario de la maquinaria.', 'La implementación del nuevo sistema ERP.', 'La producción diaria de las 500 unidades.', 'La atención continua del centro de llamadas.', 'B', 'La implementación del ERP es temporal y genera un resultado único; lo demás son operaciones continuas.'),
(3, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Programas y portafolios', 'Básica', '¿Qué es un programa según el PMI?', 'El conjunto de operaciones permanentes de un área funcional.', 'Un proyecto de gran tamaño con un presupuesto superior al promedio.', 'Un conjunto de proyectos y operaciones agrupados para alcanzar los objetivos estratégicos de la organización.', 'Proyectos, programas subsidiarios y actividades relacionados que se gestionan de forma coordinada para obtener beneficios que no se lograrían gestionándolos por separado.', 'D', 'El programa se centra en beneficios coordinados; el portafolio, en objetivos estratégicos.'),
(4, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Programas y portafolios', 'Intermedia', 'Una empresa agrupa proyectos, programas y operaciones para priorizar inversiones según su estrategia corporativa. ¿Qué está gestionando?', 'Un programa.', 'Un subproyecto.', 'Un portafolio.', 'Una fase del proyecto.', 'C', 'El portafolio agrupa componentes para alcanzar objetivos estratégicos, aunque no estén relacionados entre sí.'),
(5, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'PMO', 'Intermedia', 'Una PMO asume el control de los proyectos y los dirige directamente con sus propios directores de proyecto. ¿Qué tipo de PMO es?', 'Consultiva.', 'De apoyo.', 'De control.', 'Directiva.', 'D', 'La PMO directiva tiene el grado de control más alto: dirige los proyectos directamente.'),
(6, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'PMO', 'Intermedia', 'Una PMO proporciona plantillas, mejores prácticas, capacitación y acceso a lecciones aprendidas, pero ejerce un grado de control bajo. ¿Qué tipo de PMO es?', 'De control.', 'Directiva.', 'De apoyo.', 'Estratégica.', 'C', 'La PMO de apoyo cumple un rol consultivo con bajo grado de control.'),
(7, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Acta de constitución', 'Básica', '¿Qué documento autoriza formalmente la existencia de un proyecto y otorga al director del proyecto la autoridad para usar recursos de la organización?', 'El registro de interesados.', 'El plan para la dirección del proyecto.', 'El acta de constitución del proyecto.', 'El enunciado del alcance del proyecto.', 'C', 'El acta de constitución (project charter) autoriza el proyecto y nombra al director.'),
(8, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Acta de constitución', 'Intermedia', '¿Quién suele emitir el acta de constitución del proyecto?', 'El comité de control de cambios.', 'El equipo del proyecto.', 'El director del proyecto.', 'El patrocinador o el iniciador del proyecto.', 'D', 'El acta la emite alguien externo al proyecto con nivel suficiente para financiarlo, normalmente el patrocinador.'),
(9, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Ciclos de vida', 'Básica', 'En un ciclo de vida donde el alcance, el tiempo y el costo se determinan en las fases tempranas, ¿qué enfoque se está usando?', 'Iterativo.', 'Predictivo.', 'Incremental.', 'Adaptativo.', 'B', 'El enfoque predictivo planifica el alcance, tiempo y costo al inicio.'),
(10, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Ciclos de vida', 'Intermedia', 'En un proyecto, el producto se refina mediante ciclos repetidos y las estimaciones de tiempo y costo se ajustan a medida que el equipo comprende mejor el producto. ¿Qué ciclo de vida describe?', 'Predictivo.', 'Lineal.', 'En cascada.', 'Iterativo.', 'D', 'El ciclo iterativo desarrolla el producto mediante ciclos repetidos que lo van refinando.'),
(11, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Ciclos de vida', 'Intermedia', 'Un equipo entrega el producto en partes funcionales sucesivas, añadiendo funcionalidad en cada entrega hasta completarlo. ¿Qué ciclo de vida es?', 'Incremental.', 'En cascada.', 'Por fases secuenciales.', 'Predictivo.', 'A', 'El ciclo incremental añade funcionalidad de forma sucesiva en cada entrega.'),
(12, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Ciclos de vida', 'Intermedia', 'La construcción de un hospital usa un enfoque predictivo para la obra civil y un enfoque ágil para el software de gestión de pacientes. ¿Qué enfoque tiene el proyecto?', 'Predictivo.', 'Adaptativo puro.', 'Híbrido.', 'Incremental puro.', 'C', 'Combinar enfoques predictivos y adaptativos en un mismo proyecto es un enfoque híbrido.'),
(13, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Ciclos de vida', 'Básica', '¿Cómo se llama la revisión al final de una fase en la que se decide continuar, modificar o terminar el proyecto?', 'Retrospectiva.', 'Punto de revisión de fase (phase gate).', 'Reunión diaria.', 'Revisión del sprint.', 'B', 'El phase gate es un punto de decisión entre fases.'),
(14, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Grupos de procesos', 'Básica', '¿Cuáles son los cinco grupos de procesos de la dirección de proyectos?', 'Diseño, desarrollo, pruebas, implementación y soporte.', 'Inicio, planificación, ejecución, monitoreo y control, y cierre.', 'Planificación, compras, ejecución, calidad y cierre.', 'Inicio, análisis, ejecución, entrega y cierre.', 'B', 'Son los cinco grupos de procesos definidos por el PMI.'),
(15, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Grupos de procesos', 'Intermedia', '¿En qué grupo de procesos se identifica por primera vez a los interesados del proyecto?', 'Monitoreo y control.', 'Inicio.', 'Ejecución.', 'Planificación.', 'B', 'Identificar a los interesados es un proceso del grupo de inicio, aunque se repite durante el proyecto.'),
(16, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Principios PMBOK 7', 'Intermedia', '¿Cuál de las siguientes opciones es uno de los principios de la dirección de proyectos de la Guía del PMBOK (7.ª edición)?', 'Reducir al mínimo la interacción con los interesados.', 'Cumplir siempre el triángulo de hierro sin excepciones.', 'Ejecutar todos los procesos en el mismo orden en cada proyecto.', 'Ser un administrador diligente, respetuoso y cuidadoso.', 'D', 'La administración (stewardship) es uno de los 12 principios del PMBOK 7.'),
(17, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Dominios de desempeño', 'Avanzada', '¿Cuál de las siguientes opciones NO es un dominio de desempeño del proyecto en la Guía del PMBOK (7.ª edición)?', 'Gestión de las adquisiciones.', 'Medición.', 'Entrega.', 'Incertidumbre.', 'A', 'Adquisiciones es un área de conocimiento de ediciones anteriores, no un dominio de desempeño.'),
(18, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Adaptación (tailoring)', 'Intermedia', 'Un director de proyecto ajusta deliberadamente el enfoque, la gobernanza y los procesos para que se adapten al contexto de su proyecto. ¿Qué está haciendo?', 'Adaptación (tailoring).', 'Corrupción del alcance.', 'Ejecución rápida.', 'Gestión de la configuración.', 'A', 'La adaptación ajusta la forma de trabajo a las necesidades del proyecto y del entorno.'),
(19, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'FAE y APO', 'Intermedia', '¿Cuál de las siguientes opciones es un factor ambiental de la empresa (FAE)?', 'Las regulaciones gubernamentales del sector.', 'La base de conocimientos de proyectos anteriores.', 'Las plantillas de lecciones aprendidas.', 'Los procedimientos de control de cambios de la organización.', 'A', 'Los FAE son condiciones fuera del control del equipo; las otras opciones son activos de los procesos.'),
(20, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'FAE y APO', 'Intermedia', '¿Cuál de las siguientes opciones es un activo de los procesos de la organización (APO)?', 'El clima político del país.', 'El repositorio de lecciones aprendidas de proyectos anteriores.', 'Las condiciones del mercado.', 'La infraestructura pública disponible.', 'B', 'Las lecciones aprendidas son un APO; las otras opciones son factores ambientales.'),
(21, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Estructuras organizacionales', 'Intermedia', 'En una organización, el director del proyecto tiene poca o ninguna autoridad y el gerente funcional controla el presupuesto. ¿Qué estructura es?', 'Orientada a proyectos.', 'Matricial fuerte.', 'Matricial equilibrada.', 'Funcional.', 'D', 'En la estructura funcional el gerente funcional concentra la autoridad.'),
(22, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Estructuras organizacionales', 'Intermedia', '¿En qué estructura organizacional tiene el director del proyecto la mayor autoridad y el equipo trabaja a tiempo completo en el proyecto?', 'Matricial débil.', 'Orientada a proyectos (proyectizada).', 'Matricial equilibrada.', 'Funcional.', 'B', 'En la estructura orientada a proyectos el director tiene autoridad alta o casi total.'),
(23, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Roles', 'Básica', '¿Cuál es una responsabilidad principal del patrocinador del proyecto?', 'Realizar las pruebas técnicas de los entregables.', 'Proporcionar recursos y apoyo, y defender el proyecto ante la organización.', 'Asignar las tareas diarias del equipo.', 'Actualizar el cronograma cada semana.', 'B', 'El patrocinador financia, apoya y promueve el proyecto.'),
(24, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Roles', 'Básica', 'Según el PMI, ¿qué rol cumple el director del proyecto respecto a la integración?', 'Se ocupa solo de los aspectos técnicos del producto.', 'Integra únicamente los costos al final del proyecto.', 'Delega la integración en el patrocinador.', 'Combina y coordina el trabajo de todas las áreas para lograr los objetivos del proyecto.', 'D', 'La integración es responsabilidad del director del proyecto.'),
(25, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Interesados', 'Intermedia', 'En la matriz de poder/interés, un interesado tiene mucho poder pero poco interés en el proyecto. ¿Qué estrategia corresponde?', 'Solo monitorearlo.', 'Gestionarlo de cerca.', 'Mantenerlo satisfecho.', 'Mantenerlo informado.', 'C', 'Alto poder y bajo interés: mantener satisfecho.'),
(26, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Interesados', 'Intermedia', 'En la matriz de poder/interés, ¿qué estrategia corresponde a un interesado con poco poder y mucho interés?', 'Ignorarlo.', 'Gestionarlo de cerca.', 'Mantenerlo satisfecho.', 'Mantenerlo informado.', 'D', 'Bajo poder y alto interés: mantener informado.'),
(27, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Interesados', 'Avanzada', 'Un interesado conoce el proyecto y sus posibles impactos, pero se resiste al cambio. En la matriz de evaluación del compromiso, ¿cómo se clasifica?', 'Neutral.', 'Líder.', 'Reticente.', 'Desconocedor.', 'C', 'Reticente: conoce el proyecto pero se resiste a él.'),
(28, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Comunicaciones', 'Intermedia', 'Un equipo tiene 10 integrantes. ¿Cuántos canales de comunicación existen?', '45.', '20.', '90.', '100.', 'A', 'Fórmula n(n−1)/2 = 10×9/2 = 45.'),
(29, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Comunicaciones', 'Avanzada', 'Un equipo crece de 6 a 9 integrantes. ¿Cuántos canales de comunicación se añaden?', '18.', '21.', '36.', '3.', 'B', '6 personas: 15 canales; 9 personas: 36 canales; 36 − 15 = 21.'),
(30, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Comunicaciones', 'Intermedia', 'En el modelo de comunicación emisor-receptor, ¿qué elemento confirma que el mensaje se comprendió correctamente?', 'La codificación.', 'El medio.', 'La retroalimentación.', 'El ruido.', 'C', 'La retroalimentación confirma la comprensión del mensaje.'),
(31, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Comunicaciones', 'Intermedia', 'El equipo publica los informes del proyecto en la intranet para que los interesados los consulten cuando quieran. ¿Qué método de comunicación usa?', 'Comunicación de extracción (pull).', 'Comunicación de envío (push).', 'Comunicación informal.', 'Comunicación interactiva.', 'A', 'En la comunicación pull el receptor accede a la información cuando la necesita.'),
(32, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Comunicaciones', 'Básica', 'Enviar por correo electrónico el informe de estado semanal a los interesados es un ejemplo de:', 'Escucha activa.', 'Comunicación interactiva.', 'Comunicación de extracción (pull).', 'Comunicación de envío (push).', 'D', 'Push: se envía a receptores específicos sin garantizar que lo lean.'),
(33, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Básica', '¿Cómo define el PMI un riesgo?', 'Una restricción impuesta por el patrocinador.', 'Un evento o condición incierta que, si ocurre, tiene un efecto positivo o negativo en uno o más objetivos del proyecto.', 'Un problema que ya ocurrió y afecta al proyecto.', 'Cualquier evento con efecto exclusivamente negativo.', 'B', 'Un riesgo es incierto y puede ser una amenaza o una oportunidad.'),
(34, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Básica', 'El equipo contrata un seguro para cubrir posibles daños a los equipos durante el transporte. ¿Qué estrategia de respuesta a la amenaza aplica?', 'Aceptar.', 'Evitar.', 'Transferir.', 'Mitigar.', 'C', 'Transferir traslada el impacto de la amenaza a un tercero.'),
(35, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Intermedia', 'El director cambia el plan del proyecto para eliminar por completo una amenaza identificada. ¿Qué estrategia usa?', 'Evitar.', 'Mitigar.', 'Escalar.', 'Transferir.', 'A', 'Evitar elimina la amenaza o protege al proyecto de su impacto.'),
(36, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Intermedia', 'El equipo asigna a sus mejores recursos para asegurarse de que una oportunidad se materialice. ¿Qué estrategia usa?', 'Explotar.', 'Mejorar.', 'Aceptar.', 'Compartir.', 'A', 'Explotar busca que la oportunidad ocurra con certeza.'),
(37, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Intermedia', 'Dos empresas forman una alianza (joint venture) para aprovechar juntas una oportunidad de mercado. ¿Qué estrategia aplican?', 'Explotar.', 'Transferir.', 'Compartir.', 'Mejorar.', 'C', 'Compartir asigna la oportunidad a un tercero que puede aprovecharla mejor.'),
(38, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Intermedia', 'Un proveedor ya incumplió una entrega y esto está afectando al proyecto. ¿Dónde debe registrarse?', 'En el acta de constitución.', 'En el registro de supuestos.', 'En el registro de riesgos.', 'En el registro de incidentes.', 'D', 'Un evento que ya ocurrió es un incidente, no un riesgo.'),
(39, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Avanzada', '¿Qué reserva se destina a los riesgos no identificados (incógnitas desconocidas) y requiere aprobación de la dirección para usarse?', 'La reserva para contingencias.', 'La reserva de gestión.', 'La línea base de costos.', 'El fondo de caja chica.', 'B', 'La reserva de gestión cubre lo desconocido y no forma parte de la línea base de costos.'),
(40, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Riesgos', 'Avanzada', 'Un riesgo tiene una probabilidad del 30 % y un impacto negativo de $20 000. ¿Cuál es su valor monetario esperado (VME)?', '−$600.', '−$20 000.', '−$14 000.', '−$6 000.', 'D', 'VME = 0,30 × (−20 000) = −6 000.'),
(41, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Calidad', 'Intermedia', '¿Cuál de los siguientes es un costo de no conformidad?', 'La capacitación del equipo en estándares de calidad.', 'Las inspecciones durante la producción.', 'Las auditorías de calidad del proceso.', 'El reproceso por defectos que detectó el cliente.', 'D', 'Las fallas externas, como reprocesos y garantías, son costos de no conformidad.'),
(42, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Calidad', 'Avanzada', 'Un software tiene pocas funcionalidades pero no presenta defectos. ¿Cómo se describe?', 'Alta calidad y bajo grado.', 'Alta calidad y alto grado.', 'Baja calidad y alto grado.', 'Baja calidad y bajo grado.', 'A', 'La calidad es el cumplimiento de requisitos (sin defectos); el grado es la cantidad de características.'),
(43, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Herramientas de resolución de problemas', 'Básica', 'El equipo quiere identificar las posibles causas de retrasos recurrentes y organizarlas por categorías. ¿Qué herramienta debe usar?', 'Un histograma.', 'Un diagrama de Gantt.', 'Un diagrama de Pareto.', 'Un diagrama de causa y efecto (Ishikawa).', 'D', 'El diagrama de Ishikawa, o de espina de pescado, organiza las causas posibles por categorías.'),
(44, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Herramientas de resolución de problemas', 'Intermedia', '¿Qué herramienta ordena las causas de los defectos de mayor a menor frecuencia para concentrarse en las pocas que generan la mayoría de los problemas?', 'Un diagrama de Pareto.', 'Un diagrama de flujo.', 'Un gráfico de control.', 'Un diagrama de dispersión.', 'A', 'Pareto aplica la regla 80/20 para priorizar causas.'),
(45, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Herramientas de resolución de problemas', 'Básica', 'El equipo pregunta repetidamente "¿por qué?" hasta llegar al origen de un problema. ¿Qué técnica usa?', 'La lluvia de ideas.', 'El análisis FODA.', 'Los 5 porqués.', 'La técnica Delphi.', 'C', 'Los 5 porqués buscan la causa raíz con preguntas sucesivas.'),
(46, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Herramientas de resolución de problemas', 'Intermedia', '¿Qué herramienta muestra la relación entre dos variables, por ejemplo entre las horas de capacitación y la cantidad de errores?', 'Una hoja de verificación.', 'Un histograma.', 'Un diagrama de dispersión.', 'Un diagrama de Pareto.', 'C', 'El diagrama de dispersión muestra la correlación entre dos variables.'),
(47, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Herramientas de resolución de problemas', 'Avanzada', 'En un gráfico de control aparecen siete puntos consecutivos por encima de la media, todos dentro de los límites de control. ¿Qué indica?', 'Es un error de medición que puede ignorarse.', 'El proceso está fuera de control y debe investigarse.', 'Se deben ampliar los límites de control.', 'El proceso está bajo control porque ningún punto supera los límites.', 'B', 'La regla de los siete puntos indica una causa especial aunque no se superen los límites.'),
(48, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Control de cambios', 'Intermedia', 'Un interesado pide directamente a un miembro del equipo que añada una funcionalidad no planificada. ¿Qué debe hacer primero el director del proyecto?', 'Registrar la solicitud y evaluar su impacto según el proceso de control integrado de cambios.', 'Pedir al equipo que trabaje horas extra para incluirla.', 'Rechazar la solicitud porque no estaba en el plan.', 'Implementar el cambio de inmediato para satisfacer al interesado.', 'A', 'Todo cambio debe documentarse, analizarse y aprobarse formalmente.'),
(49, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Control de cambios', 'Básica', 'En un proyecto predictivo, ¿quién suele aprobar o rechazar las solicitudes de cambio?', 'El cliente final, sin consultar a nadie.', 'El comité de control de cambios (CCB).', 'El miembro del equipo que recibió la solicitud.', 'El proveedor principal.', 'B', 'El CCB revisa y decide sobre los cambios según el plan de gestión de cambios.'),
(50, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Lecciones aprendidas', 'Básica', '¿Cuándo deben registrarse las lecciones aprendidas?', 'A lo largo de todo el proyecto, consolidándolas al cierre.', 'Solo al inicio del proyecto.', 'Solo cuando el proyecto fracasa.', 'Solo al final del proyecto.', 'A', 'Las lecciones aprendidas se recogen de forma continua para aprovecharlas pronto.'),
(51, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Cierre', 'Intermedia', '¿Cuál de las siguientes es una actividad típica del cierre del proyecto?', 'Identificar a los interesados por primera vez.', 'Crear la estructura de desglose del trabajo.', 'Desarrollar el acta de constitución.', 'Obtener la aceptación formal de los entregables y archivar la documentación.', 'D', 'En el cierre se formaliza la aceptación, se transfiere el producto y se archiva la información.'),
(52, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Equipo y conflictos', 'Intermedia', '¿Qué técnica de resolución de conflictos suele generar el resultado más duradero?', 'Colaborar o resolver el problema.', 'Suavizar o acomodar.', 'Forzar o dirigir.', 'Retirarse o evitar.', 'A', 'Colaborar integra varios puntos de vista y genera consenso y compromiso.'),
(53, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Equipo y conflictos', 'Intermedia', 'Un equipo recién formado discute sobre roles y formas de trabajo, y surgen conflictos. Según el modelo de Tuckman, ¿en qué etapa está?', 'Formación (forming).', 'Turbulencia (storming).', 'Normalización (norming).', 'Desempeño (performing).', 'B', 'En la turbulencia surgen los conflictos mientras el equipo se ajusta.'),
(54, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Liderazgo', 'Intermedia', 'Un líder prioriza las necesidades de su equipo, elimina impedimentos y fomenta su crecimiento. ¿Qué estilo de liderazgo aplica?', 'Liderazgo laissez-faire.', 'Liderazgo autocrático.', 'Liderazgo transaccional.', 'Liderazgo de servicio (servant leadership).', 'D', 'El líder de servicio pone primero al equipo y lo facilita.'),
(55, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Liderazgo', 'Intermedia', 'El equipo sigue las indicaciones del director porque reconoce su amplio conocimiento técnico. ¿Qué tipo de poder ejerce el director?', 'Poder de recompensa.', 'Poder coercitivo.', 'Poder experto.', 'Poder legítimo.', 'C', 'El poder experto se basa en los conocimientos y habilidades.'),
(56, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Motivación', 'Avanzada', 'Según la teoría de Herzberg, ¿cuál de los siguientes es un factor motivador y no un factor de higiene?', 'Las políticas de la empresa.', 'Las condiciones de trabajo.', 'El salario.', 'El reconocimiento por los logros.', 'D', 'Los motivadores son el logro, el reconocimiento y el crecimiento; el salario y las condiciones son factores de higiene.'),
(57, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Ética', 'Básica', '¿Cuál de los siguientes es uno de los cuatro valores del Código de Ética y Conducta Profesional del PMI?', 'Puntualidad.', 'Competitividad.', 'Rentabilidad.', 'Equidad.', 'D', 'Los cuatro valores son responsabilidad, respeto, equidad y honestidad.'),
(58, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Ética', 'Intermedia', 'Un director descubre que la empresa de un familiar participa en la licitación que él debe evaluar. ¿Qué debe hacer?', 'Descalificar a la empresa de su familiar sin informar a nadie.', 'Revelar el conflicto de intereses y abstenerse de participar en la decisión.', 'Evaluar la propuesta con normalidad si cree que será objetivo.', 'Favorecer a la empresa si su oferta es la más barata.', 'B', 'El código de ética exige revelar los conflictos de intereses y actuar con equidad.'),
(59, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Roles', 'Intermedia', 'En una matriz RACI, ¿cuántas personas deberían tener la letra "A" (quien rinde cuentas) en cada actividad?', 'Ninguna.', 'Al menos dos.', 'Todo el equipo.', 'Solo una.', 'D', 'Debe haber un único responsable de rendir cuentas por actividad para evitar ambigüedades.'),
(60, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Reuniones', 'Básica', '¿Cuál es el propósito principal de la reunión de lanzamiento (kick-off)?', 'Alinear al equipo y a los interesados sobre los objetivos, los roles y la forma de trabajo.', 'Evaluar el desempeño individual del equipo.', 'Aprobar el cierre del proyecto.', 'Negociar los contratos con los proveedores.', 'A', 'El kick-off marca el comienzo del trabajo y alinea expectativas.'),
(61, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Supuestos y restricciones', 'Básica', 'Un regulador establece una fecha límite que el proyecto no puede cambiar. ¿Qué es esa fecha?', 'Un supuesto.', 'Una restricción.', 'Un riesgo.', 'Un hito opcional.', 'B', 'Una restricción es un factor que limita las opciones del proyecto.'),
(62, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Supuestos y restricciones', 'Básica', 'La afirmación "Se asume que el proveedor entregará los equipos a tiempo" debe documentarse en:', 'El registro de supuestos.', 'El calendario de recursos.', 'El registro de incidentes.', 'El registro de cambios.', 'A', 'Los supuestos se consideran ciertos sin pruebas y se documentan para validarlos.'),
(63, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Resolución de problemas', 'Intermedia', 'Un miembro clave del equipo renuncia de forma inesperada. ¿Qué debe hacer primero el director del proyecto?', 'Contratar de inmediato a un reemplazo sin analizar el impacto.', 'Evaluar el impacto en el plan y revisar si había una respuesta planificada en el registro de riesgos.', 'Informar al cliente que el proyecto se cancelará.', 'Retrasar todo el proyecto hasta encontrar a otra persona.', 'B', 'Primero se analiza el impacto y se usan las respuestas planificadas, y después se actúa.'),
(64, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Interesados', 'Avanzada', 'Un interesado clave muestra poco compromiso y nadie había previsto esa situación en el plan. ¿Qué debe hacer el director del proyecto?', 'Analizar las causas y actualizar el plan de involucramiento de los interesados con nuevas acciones.', 'Esperar a que cambie de actitud por sí mismo.', 'Escalar el caso de inmediato al patrocinador para que lo reemplace.', 'Retirarlo de la lista de interesados.', 'A', 'El involucramiento de los interesados se gestiona de forma activa y el plan se actualiza cuando hace falta.'),
(65, 'Fundamentos y conceptos básicos de la dirección de proyectos', 'Gestión del conocimiento', 'Intermedia', '¿Cuál es la diferencia entre el conocimiento explícito y el conocimiento tácito?', 'El explícito se puede documentar fácilmente; el tácito es personal y difícil de expresar, como la experiencia.', 'No hay diferencia: ambos términos significan lo mismo.', 'El explícito es confidencial; el tácito es público.', 'El tácito siempre está en manuales; el explícito, solo en la mente de las personas.', 'A', 'El conocimiento tácito se transmite sobre todo con interacción y networking.'),
(66, 'Metodologías predictivas basadas en planes', 'Alcance', 'Básica', '¿Qué es la estructura de desglose del trabajo (EDT/WBS)?', 'Un diagrama de las dependencias entre actividades.', 'Un organigrama de los integrantes del equipo.', 'Una lista de actividades ordenadas cronológicamente.', 'Una descomposición jerárquica del alcance total del trabajo que realizará el equipo.', 'D', 'La EDT descompone el alcance en entregables y paquetes de trabajo.'),
(67, 'Metodologías predictivas basadas en planes', 'Alcance', 'Básica', '¿Cómo se llama el nivel más bajo de la EDT, en el que se pueden estimar y gestionar el costo y la duración?', 'Cuenta de control.', 'Actividad resumen.', 'Paquete de trabajo.', 'Hito.', 'C', 'El paquete de trabajo es el nivel más bajo de la EDT.'),
(68, 'Metodologías predictivas basadas en planes', 'Alcance', 'Intermedia', '¿Qué componentes forman la línea base del alcance?', 'El enunciado del alcance, el presupuesto y el registro de riesgos.', 'La EDT, el cronograma y la línea base de costos.', 'El acta de constitución, la EDT y el cronograma.', 'El enunciado del alcance, la EDT y el diccionario de la EDT.', 'D', 'La línea base del alcance es la versión aprobada de esos tres documentos.'),
(69, 'Metodologías predictivas basadas en planes', 'Alcance', 'Intermedia', '¿Qué establece la regla del 100 % en la EDT?', 'La EDT debe incluir todo el trabajo del proyecto y nada más.', 'El presupuesto debe asignarse por completo en la primera fase.', 'Todos los interesados deben aprobar el 100 % de los entregables.', 'Cada paquete de trabajo debe completarse al 100 % antes de iniciar otro.', 'A', 'La EDT incluye el 100 % del trabajo definido en el alcance.'),
(70, 'Metodologías predictivas basadas en planes', 'Alcance', 'Intermedia', '¿Cuál es el propósito del proceso Validar el alcance?', 'Formalizar la aceptación de los entregables completados por parte del cliente o el patrocinador.', 'Registrar los cambios de alcance aprobados.', 'Crear la EDT del proyecto.', 'Verificar que los entregables cumplan los requisitos de calidad internos.', 'A', 'Validar el alcance obtiene la aceptación formal; Controlar la calidad verifica que el entregable sea correcto.'),
(71, 'Metodologías predictivas basadas en planes', 'Alcance', 'Básica', 'El alcance de un proyecto crece poco a poco con cambios que no pasan por el control de cambios. ¿Cómo se llama esto?', 'Elaboración progresiva.', 'Corrupción del alcance (scope creep).', 'Ejecución rápida.', 'Enchapado en oro (gold plating).', 'B', 'El scope creep es la expansión no controlada del alcance.'),
(72, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Básica', '¿Qué es la ruta crítica?', 'La secuencia de actividades más larga, que determina la duración más corta posible del proyecto.', 'La secuencia de actividades más corta del proyecto.', 'Las actividades con mayor costo.', 'Las actividades de mayor riesgo técnico.', 'A', 'La ruta crítica determina la duración mínima del proyecto.'),
(73, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Avanzada', 'Un proyecto tiene dos rutas: A(3 días) → B(4 días) → D(2 días) y A(3 días) → C(6 días) → D(2 días). ¿Cuánto dura el proyecto?', '9 días.', '11 días.', '6 días.', '15 días.', 'B', 'Ruta A-B-D: 9 días; ruta A-C-D: 11 días. La ruta más larga define la duración.'),
(74, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Avanzada', 'Con las rutas A(3) → B(4) → D(2) y A(3) → C(6) → D(2), ¿cuál es la holgura total de la actividad B?', '4 días.', '0 días.', '2 días.', '11 días.', 'C', 'La ruta crítica dura 11 días y la ruta de B dura 9, así que B tiene 2 días de holgura.'),
(75, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Básica', '¿Cuánta holgura total suelen tener las actividades de la ruta crítica?', 'Un día.', 'Cero.', 'Una holgura ilimitada.', 'La misma que la actividad más larga.', 'B', 'Las actividades críticas no tienen holgura: cualquier retraso afecta la fecha final.'),
(76, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Básica', '¿Cuál es el tipo de dependencia más común en un diagrama de red?', 'Final a final (FF).', 'Final a inicio (FS).', 'Inicio a inicio (SS).', 'Inicio a final (SF).', 'B', 'En la relación FS, la sucesora empieza cuando termina la predecesora.'),
(77, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Intermedia', 'La actividad sucesora empieza 3 días antes de que termine su predecesora. ¿Qué se aplica?', 'Un retraso (lag).', 'Una holgura libre.', 'Una restricción obligatoria.', 'Un adelanto (lead).', 'D', 'El adelanto permite que la sucesora empiece antes.'),
(78, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Intermedia', 'Después de vaciar el concreto hay que esperar 3 días de secado antes de continuar. ¿Qué se aplica entre ambas actividades?', 'Una intensificación.', 'Un adelanto (lead).', 'Un retraso (lag).', 'Una ejecución rápida.', 'C', 'El retraso es el tiempo de espera obligatorio entre dos actividades.'),
(79, 'Metodologías predictivas basadas en planes', 'Compresión del cronograma', 'Intermedia', 'Para acortar el cronograma, el director agrega recursos a las actividades de la ruta crítica. ¿Qué técnica usa y cuál es su efecto típico?', 'Intensificación (crashing), que suele aumentar el costo.', 'Ejecución rápida (fast tracking), que suele aumentar el riesgo.', 'Nivelación de recursos, que suele acortar la ruta crítica.', 'Estabilización de recursos, que no tiene efecto en el costo.', 'A', 'La intensificación añade recursos y suele elevar el costo.'),
(80, 'Metodologías predictivas basadas en planes', 'Compresión del cronograma', 'Intermedia', 'El equipo realiza en paralelo actividades que normalmente serían secuenciales. ¿Qué técnica usa y cuál es su riesgo principal?', 'Intensificación (crashing), que aumenta el costo directo.', 'Estimación análoga, que reduce la precisión.', 'Ejecución rápida (fast tracking), que puede generar reprocesos y más riesgo.', 'Nivelación de recursos, que alarga el proyecto.', 'C', 'La ejecución rápida solapa actividades y eso aumenta el riesgo.'),
(81, 'Metodologías predictivas basadas en planes', 'Estimación', 'Avanzada', 'Usando la estimación PERT de tres valores (beta), una actividad tiene: optimista = 4, más probable = 6 y pesimista = 14 días. ¿Cuál es la duración esperada?', '8 días.', '24 días.', '7 días.', '6 días.', 'C', '(O + 4M + P) / 6 = (4 + 24 + 14) / 6 = 7.'),
(82, 'Metodologías predictivas basadas en planes', 'Estimación', 'Básica', '¿Qué técnica estima usando datos reales de un proyecto anterior similar y es rápida pero poco precisa?', 'Estimación de tres valores.', 'Estimación ascendente.', 'Estimación paramétrica.', 'Estimación análoga.', 'D', 'La estimación análoga, o top-down, se basa en proyectos similares.'),
(83, 'Metodologías predictivas basadas en planes', 'Estimación', 'Intermedia', 'El costo de una obra se calcula multiplicando 200 m² por $500 por m², lo que da $100 000. ¿Qué técnica se usó?', 'Estimación análoga.', 'Estimación ascendente.', 'Juicio de expertos.', 'Estimación paramétrica.', 'D', 'La estimación paramétrica usa una relación estadística entre variables.'),
(84, 'Metodologías predictivas basadas en planes', 'Estimación', 'Intermedia', '¿Qué técnica estima cada paquete de trabajo por separado y suma los resultados, logrando en general la mayor precisión?', 'Estimación por consenso Delphi.', 'Estimación paramétrica.', 'Estimación análoga.', 'Estimación ascendente (bottom-up).', 'D', 'La estimación ascendente agrega estimaciones detalladas y es la más precisa.'),
(85, 'Metodologías predictivas basadas en planes', 'Valor ganado', 'Avanzada', 'Un proyecto tiene EV = $40 000, PV = $50 000 y AC = $45 000. ¿Cuál es su situación?', 'Va retrasado y por encima del presupuesto.', 'Va adelantado y por debajo del presupuesto.', 'Va retrasado y por debajo del presupuesto.', 'Va adelantado y por encima del presupuesto.', 'A', 'SV = EV − PV = −10 000 (retraso); CV = EV − AC = −5 000 (sobrecosto).'),
(86, 'Metodologías predictivas basadas en planes', 'Valor ganado', 'Avanzada', 'Un proyecto tiene EV = $60 000 y PV = $50 000. ¿Cuál es su índice de desempeño del cronograma (SPI) y qué indica?', 'SPI = 10 000: va adelantado respecto al cronograma.', 'SPI = 1,2: va adelantado respecto al cronograma.', 'SPI = 0,83: va retrasado respecto al cronograma.', 'SPI = 1,2: va por encima del presupuesto.', 'B', 'SPI = EV / PV = 60 / 50 = 1,2; si es mayor que 1, va adelantado.'),
(87, 'Metodologías predictivas basadas en planes', 'Valor ganado', 'Avanzada', 'El presupuesto hasta la conclusión (BAC) es $100 000 y el CPI es 0,8. Si el desempeño de costos sigue igual, ¿cuál es la estimación a la conclusión (EAC)?', '$80 000.', '$120 000.', '$125 000.', '$100 000.', 'C', 'EAC = BAC / CPI = 100 000 / 0,8 = 125 000.'),
(88, 'Metodologías predictivas basadas en planes', 'Valor ganado', 'Intermedia', '¿Qué indica una variación a la conclusión (VAC) negativa?', 'Que ya se gastó todo el presupuesto.', 'Que se prevé terminar el proyecto por debajo del presupuesto.', 'Que se prevé terminar el proyecto por encima del presupuesto.', 'Que el proyecto va adelantado respecto al cronograma.', 'C', 'VAC = BAC − EAC; si es negativa, hay un sobrecosto previsto.'),
(89, 'Metodologías predictivas basadas en planes', 'Costos', 'Intermedia', '¿Qué incluye el presupuesto total del proyecto que NO incluye la línea base de costos?', 'La reserva para contingencias.', 'Los costos de los paquetes de trabajo.', 'La reserva de gestión.', 'Los costos de las actividades.', 'C', 'Presupuesto = línea base de costos (con contingencias) + reserva de gestión.'),
(90, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Básica', 'En el cronograma de un proyecto, ¿qué duración tiene un hito?', 'Cero.', 'Una semana.', 'La duración de la fase.', 'Un día.', 'A', 'Un hito marca un punto o evento significativo y no tiene duración.'),
(91, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Avanzada', 'Al ajustar las fechas por la disponibilidad limitada de un recurso clave, la ruta crítica cambia y el proyecto se alarga. ¿Qué técnica se aplicó?', 'Ejecución rápida.', 'Estabilización de recursos.', 'Intensificación.', 'Nivelación de recursos.', 'D', 'La nivelación puede cambiar la ruta crítica; la estabilización solo usa la holgura disponible.'),
(92, 'Metodologías predictivas basadas en planes', 'Adquisiciones', 'Intermedia', '¿Qué tipo de contrato traslada el mayor riesgo al vendedor?', 'Costo más porcentaje del costo.', 'Precio fijo cerrado.', 'Tiempo y materiales.', 'Costo más honorarios fijos.', 'B', 'En el precio fijo cerrado, el vendedor asume los sobrecostos.'),
(93, 'Metodologías predictivas basadas en planes', 'Adquisiciones', 'Intermedia', '¿Qué tipo de contrato traslada el mayor riesgo de costos al comprador?', 'Precio fijo con ajuste económico de precio.', 'Precio fijo más honorarios de incentivo.', 'Precio fijo cerrado.', 'Costo reembolsable (por ejemplo, costo más porcentaje del costo).', 'D', 'En los contratos de costo reembolsable, el comprador paga los costos reales.'),
(94, 'Metodologías predictivas basadas en planes', 'Adquisiciones', 'Intermedia', 'Se necesita contratar a un especialista con urgencia y el alcance aún no está claramente definido. ¿Qué tipo de contrato es más adecuado?', 'Contrato llave en mano.', 'Precio fijo con incentivo.', 'Tiempo y materiales.', 'Precio fijo cerrado.', 'C', 'Tiempo y materiales sirve para contrataciones rápidas o con un alcance poco definido.'),
(95, 'Metodologías predictivas basadas en planes', 'Planificación', 'Básica', '¿Qué documento describe cómo se ejecutará, monitoreará, controlará y cerrará el proyecto, e integra los planes subsidiarios y las líneas base?', 'El plan para la dirección del proyecto.', 'El acta de constitución del proyecto.', 'El enunciado del trabajo (SOW).', 'El registro de interesados.', 'A', 'El plan para la dirección del proyecto integra todos los planes y las líneas base.'),
(96, 'Metodologías predictivas basadas en planes', 'Cronograma', 'Básica', '¿Qué herramienta muestra las actividades del cronograma como barras horizontales a lo largo del tiempo?', 'El diagrama de Pareto.', 'El histograma de recursos.', 'El diagrama de Gantt.', 'El diagrama de red.', 'C', 'El diagrama de Gantt representa la duración de las actividades con barras en una escala de tiempo.'),
(97, 'Marcos y metodologías ágiles', 'Manifiesto Ágil', 'Básica', 'Según el Manifiesto Ágil, ¿qué se valora más que los procesos y las herramientas?', 'Los individuos y las interacciones.', 'La negociación contractual.', 'La documentación extensiva.', 'Seguir un plan.', 'A', '"Individuos e interacciones sobre procesos y herramientas".'),
(98, 'Marcos y metodologías ágiles', 'Manifiesto Ágil', 'Básica', 'Según el Manifiesto Ágil, ¿qué se valora más que la documentación extensiva?', 'El software funcionando.', 'Los procesos y las herramientas.', 'Seguir un plan.', 'La negociación contractual.', 'A', '"Software funcionando sobre documentación extensiva".'),
(99, 'Marcos y metodologías ágiles', 'Manifiesto Ágil', 'Básica', 'Según el Manifiesto Ágil, ¿qué se valora más que seguir un plan?', 'La documentación extensiva.', 'Responder ante el cambio.', 'El control estricto del alcance.', 'Los contratos detallados.', 'B', '"Responder ante el cambio sobre seguir un plan".'),
(100, 'Marcos y metodologías ágiles', 'Manifiesto Ágil', 'Intermedia', '¿Cuántos principios acompañan a los cuatro valores del Manifiesto Ágil?', '15.', '12.', '10.', '4.', 'B', 'El Manifiesto Ágil tiene 4 valores y 12 principios.'),
(101, 'Marcos y metodologías ágiles', 'Scrum', 'Básica', '¿Cuáles son las responsabilidades (roles) definidas en Scrum?', 'Product Owner, director del proyecto y testers.', 'Product Owner, Scrum Master y Developers.', 'Director del proyecto, patrocinador y equipo.', 'Scrum Master, analista de negocios y arquitecto.', 'B', 'La Guía Scrum define tres responsabilidades: Product Owner, Scrum Master y Developers.'),
(102, 'Marcos y metodologías ágiles', 'Scrum', 'Básica', '¿Quién es responsable de maximizar el valor del producto y de gestionar el Product Backlog?', 'Los Developers.', 'El patrocinador.', 'El Product Owner.', 'El Scrum Master.', 'C', 'El Product Owner ordena y gestiona el Product Backlog para maximizar el valor.'),
(103, 'Marcos y metodologías ágiles', 'Scrum', 'Básica', '¿Cuál es una responsabilidad principal del Scrum Master?', 'Decidir qué funcionalidades entran en el producto.', 'Asignar las tareas a cada desarrollador.', 'Aprobar el presupuesto del proyecto.', 'Facilitar el trabajo del equipo y ayudar a eliminar los impedimentos.', 'D', 'El Scrum Master es un líder de servicio que facilita el proceso y elimina impedimentos.'),
(104, 'Marcos y metodologías ágiles', 'Scrum', 'Básica', 'Según la Guía Scrum, ¿cuál es la duración máxima de un sprint?', 'Un mes.', 'Una semana.', 'Dos meses.', 'Tres meses.', 'A', 'Los sprints duran un mes o menos para mantener ciclos de retroalimentación cortos.'),
(105, 'Marcos y metodologías ágiles', 'Scrum', 'Intermedia', '¿Cuál es el propósito del Daily Scrum?', 'Estimar todo el Product Backlog.', 'Informar al director del proyecto sobre el desempeño individual.', 'Inspeccionar el avance hacia el objetivo del sprint y adaptar el plan para las siguientes 24 horas.', 'Presentar el incremento a los interesados.', 'C', 'El Daily Scrum es un evento de 15 minutos para que los Developers se sincronicen y adapten su plan.'),
(106, 'Marcos y metodologías ágiles', 'Scrum', 'Intermedia', '¿En qué evento de Scrum se presenta el incremento a los interesados para obtener su retroalimentación?', 'Daily Scrum.', 'Sprint Planning.', 'Sprint Retrospective.', 'Sprint Review.', 'D', 'En la Sprint Review se inspecciona el resultado del sprint junto con los interesados.'),
(107, 'Marcos y metodologías ágiles', 'Scrum', 'Intermedia', '¿Cuál es el propósito de la Sprint Retrospective?', 'Evaluar el desempeño individual de cada miembro.', 'Repriorizar el Product Backlog.', 'Demostrar el producto al cliente.', 'Planificar formas de mejorar la calidad y la eficacia del trabajo del equipo.', 'D', 'La retrospectiva busca la mejora continua del equipo.'),
(108, 'Marcos y metodologías ágiles', 'Scrum', 'Intermedia', '¿Qué se define durante la Sprint Planning?', 'Solo el presupuesto del sprint.', 'El cierre formal del proyecto.', 'Las lecciones aprendidas del sprint anterior.', 'Por qué es valioso el sprint, qué se puede hacer y cómo se hará el trabajo.', 'D', 'La Sprint Planning define el objetivo del sprint, los elementos seleccionados y el plan para entregarlos.'),
(109, 'Marcos y metodologías ágiles', 'Scrum', 'Intermedia', '¿Qué es la Definición de Terminado (Definition of Done)?', 'La fecha en que termina el proyecto.', 'El documento de aceptación firmado por el patrocinador.', 'La lista de tareas pendientes del sprint.', 'Una descripción formal del estado que debe cumplir un incremento para satisfacer las medidas de calidad del producto.', 'D', 'La DoD crea transparencia sobre cuándo un trabajo está realmente terminado.'),
(110, 'Marcos y metodologías ágiles', 'Scrum', 'Básica', '¿Qué es un incremento en Scrum?', 'Un documento de requisitos.', 'Un aumento del presupuesto aprobado.', 'Un paso concreto hacia el objetivo del producto que cumple la Definición de Terminado y es utilizable.', 'Una nueva persona que se suma al equipo.', 'C', 'Cada incremento se suma a los anteriores y debe ser utilizable.'),
(111, 'Marcos y metodologías ágiles', 'Métricas ágiles', 'Avanzada', 'Un equipo tiene una velocidad promedio de 20 puntos de historia por sprint y quedan 120 puntos en el backlog. ¿Cuántos sprints necesitará aproximadamente?', '12 sprints.', '6 sprints.', '4 sprints.', '20 sprints.', 'B', '120 / 20 = 6 sprints.'),
(112, 'Marcos y metodologías ágiles', 'Estimación ágil', 'Intermedia', '¿Qué miden los puntos de historia?', 'El costo en dinero de cada historia.', 'La cantidad de personas necesarias.', 'Las horas exactas que tomará una tarea.', 'El esfuerzo, la complejidad y la incertidumbre relativos de una historia de usuario.', 'D', 'Los puntos de historia son una estimación relativa, no un tiempo absoluto.'),
(113, 'Marcos y metodologías ágiles', 'Estimación ágil', 'Intermedia', 'Los miembros del equipo muestran cartas numeradas al mismo tiempo para estimar una historia y conversan sobre las diferencias. ¿Qué técnica usan?', 'Planning Poker.', 'Técnica Delphi escrita.', 'Estimación paramétrica.', 'Diagrama de afinidad.', 'A', 'El Planning Poker combina estimación relativa y consenso del equipo.'),
(114, 'Marcos y metodologías ágiles', 'Historias de usuario', 'Básica', '¿Cuál es el formato habitual de una historia de usuario?', 'Como <rol>, quiero <funcionalidad> para <beneficio>.', 'El sistema deberá <requisito técnico>.', 'Si <condición>, entonces <acción>.', 'Tarea: <descripción> – Responsable: <nombre>.', 'A', 'Este formato pone el foco en el usuario y en el valor.'),
(115, 'Marcos y metodologías ágiles', 'Historias de usuario', 'Intermedia', 'En el acrónimo INVEST para historias de usuario, ¿qué significa la "I"?', 'Independiente.', 'Integrada.', 'Importante.', 'Iterativa.', 'A', 'INVEST: Independiente, Negociable, Valiosa, Estimable, Pequeña (Small) y Testeable.'),
(116, 'Marcos y metodologías ágiles', 'Historias de usuario', 'Intermedia', '¿Para qué sirven los criterios de aceptación de una historia de usuario?', 'Para asignar la historia a un desarrollador.', 'Para definir las condiciones que debe cumplir la historia para que el Product Owner la acepte.', 'Para estimar el costo de la historia.', 'Para definir la duración del sprint.', 'B', 'Los criterios de aceptación hacen que la historia sea verificable.'),
(117, 'Marcos y metodologías ágiles', 'Kanban', 'Básica', '¿Cuál es una práctica fundamental de Kanban?', 'Planificar todo el alcance al inicio.', 'Trabajar siempre en sprints de dos semanas.', 'Tener un Scrum Master asignado.', 'Limitar el trabajo en curso (WIP).', 'D', 'Limitar el WIP mejora el flujo y deja ver los cuellos de botella.'),
(118, 'Marcos y metodologías ágiles', 'Kanban', 'Intermedia', '¿Cuál es una diferencia clave entre Kanban y Scrum?', 'Kanban no permite visualizar el trabajo.', 'Kanban requiere un Product Owner y un Scrum Master.', 'Kanban se basa en un flujo continuo sin iteraciones obligatorias de duración fija.', 'Kanban exige sprints de un mes.', 'C', 'Kanban gestiona el flujo de forma continua y Scrum usa sprints de duración fija.'),
(119, 'Marcos y metodologías ágiles', 'Métricas ágiles', 'Avanzada', '¿Qué mide el tiempo de ciclo (cycle time) en Kanban?', 'El tiempo desde que el cliente hace la solicitud hasta que la recibe.', 'La duración de un sprint.', 'El tiempo desde que se empieza a trabajar en un elemento hasta que se completa.', 'El tiempo total del proyecto.', 'C', 'El lead time cuenta desde la solicitud; el cycle time, desde que comienza el trabajo.'),
(120, 'Marcos y metodologías ágiles', 'Métricas ágiles', 'Básica', '¿Qué muestra un gráfico de trabajo pendiente (burndown chart)?', 'El trabajo completado y el alcance total.', 'La cantidad de defectos por categoría.', 'El trabajo restante a lo largo del tiempo.', 'El costo real frente al planificado.', 'C', 'El burndown muestra cómo disminuye el trabajo pendiente.'),
(121, 'Marcos y metodologías ágiles', 'Métricas ágiles', 'Intermedia', '¿Qué gráfico muestra tanto el trabajo completado como los cambios en el alcance total del proyecto?', 'El gráfico de trabajo realizado (burnup chart).', 'El histograma de recursos.', 'El diagrama de Pareto.', 'El gráfico de trabajo pendiente (burndown chart).', 'A', 'El burnup muestra por separado el trabajo completado y el alcance total.'),
(122, 'Marcos y metodologías ágiles', 'Métricas ágiles', 'Avanzada', '¿Qué herramienta ágil ayuda a detectar cuellos de botella al mostrar cuántos elementos hay en cada estado del flujo a lo largo del tiempo?', 'El diagrama de flujo acumulado (CFD).', 'El gráfico de control.', 'El diagrama de Gantt.', 'La matriz RACI.', 'A', 'En el CFD, una banda que se ensancha indica un cuello de botella.'),
(123, 'Marcos y metodologías ágiles', 'Producto', 'Básica', '¿Qué es un producto mínimo viable (MVP)?', 'La versión final del producto con todas sus funcionalidades.', 'El producto con el menor costo posible, sin importar su utilidad.', 'La versión más simple del producto que permite validar hipótesis con usuarios reales.', 'Un documento con los requisitos mínimos.', 'C', 'El MVP busca aprender rápido con el menor esfuerzo.'),
(124, 'Marcos y metodologías ágiles', 'Prácticas ágiles', 'Intermedia', 'Antes de estimar una historia compleja, el equipo dedica un tiempo limitado a investigar una tecnología desconocida. ¿Cómo se llama esta actividad?', 'Refactorización.', 'Swarming.', 'Retrospectiva.', 'Spike.', 'D', 'Un spike es una investigación acotada en el tiempo para reducir la incertidumbre.'),
(125, 'Marcos y metodologías ágiles', 'Prácticas ágiles', 'Básica', '¿Qué significa trabajar con timeboxing?', 'Ampliar el tiempo hasta terminar todo el alcance.', 'Asignar un período de tiempo fijo y máximo a una actividad o evento.', 'Registrar las horas trabajadas por cada persona.', 'Medir el tiempo de respuesta del sistema.', 'B', 'El timebox fija la duración y obliga a priorizar.'),
(126, 'Marcos y metodologías ágiles', 'Prácticas ágiles', 'Intermedia', 'El equipo pega en la pared, a la vista de todos, su tablero de tareas y su burndown actualizado. ¿Cómo se llama esta práctica?', 'Repositorio de lecciones aprendidas.', 'Registro de incidentes.', 'Matriz de trazabilidad.', 'Radiador de información.', 'D', 'El radiador de información hace visible el estado del trabajo para todos.'),
(127, 'Marcos y metodologías ágiles', 'Prácticas ágiles', 'Intermedia', 'En Extreme Programming (XP), dos desarrolladores trabajan juntos en una misma estación: uno escribe el código y el otro lo revisa. ¿Qué práctica es?', 'Desarrollo guiado por pruebas.', 'Propiedad colectiva del código.', 'Programación en parejas.', 'Integración continua.', 'C', 'La programación en parejas mejora la calidad y el conocimiento compartido.'),
(128, 'Marcos y metodologías ágiles', 'Equipos ágiles', 'Básica', '¿Qué caracteriza a un equipo ágil multifuncional?', 'Cada miembro trabaja en un área funcional distinta y separada.', 'Tiene todas las habilidades necesarias para entregar un incremento de valor sin depender de otros equipos.', 'Depende de un gerente que asigna todas las tareas.', 'Cambia de integrantes en cada sprint.', 'B', 'Los equipos multifuncionales reducen dependencias y traspasos.'),
(129, 'Marcos y metodologías ágiles', 'Gestión del cambio ágil', 'Intermedia', 'A mitad de un sprint, un interesado pide al equipo que añada una nueva funcionalidad urgente. ¿Qué es lo más adecuado?', 'Cancelar el sprint y empezar uno nuevo.', 'Rechazarla porque los sprints no admiten cambios.', 'Añadirla de inmediato al sprint actual.', 'Derivar la solicitud al Product Owner para que la evalúe y la priorice en el Product Backlog.', 'D', 'El Product Owner gestiona las prioridades; el objetivo del sprint se protege.'),
(130, 'Marcos y metodologías ágiles', 'Impedimentos', 'Intermedia', 'El equipo no puede avanzar porque otro departamento no le da acceso a un servidor. ¿Quién debe ayudar principalmente a resolverlo?', 'El desarrollador más antiguo.', 'El cliente.', 'El Scrum Master.', 'El Product Owner.', 'C', 'El Scrum Master ayuda a eliminar los impedimentos del equipo.'),
(131, 'Marcos y metodologías ágiles', 'Backlog', 'Intermedia', '¿Qué es el refinamiento del Product Backlog?', 'Eliminar todo el backlog al final del sprint.', 'Congelar el backlog para que nadie lo modifique.', 'Aprobar el presupuesto de cada historia.', 'Dividir los elementos del backlog y añadirles detalle, como descripción, orden y tamaño.', 'D', 'El refinamiento es una actividad continua para preparar elementos listos para los sprints.'),
(132, 'Marcos y metodologías ágiles', 'Agilidad a escala', 'Avanzada', 'Varios equipos Scrum trabajan sobre un mismo producto y necesitan coordinar sus dependencias con frecuencia. ¿Qué práctica es adecuada?', 'Scrum de Scrums.', 'Volver a un enfoque en cascada.', 'Eliminar al Product Owner.', 'Una única retrospectiva anual.', 'A', 'En el Scrum de Scrums, representantes de cada equipo coordinan las dependencias.'),
(133, 'Marcos de análisis de negocios', 'Rol del analista de negocios', 'Básica', '¿Cuál es el propósito principal del análisis de negocios?', 'Auditar los estados financieros de la empresa.', 'Programar el software del producto.', 'Identificar las necesidades del negocio y recomendar soluciones que aporten valor.', 'Gestionar el cronograma y el presupuesto del proyecto.', 'C', 'El análisis de negocios conecta las necesidades con las soluciones de valor.'),
(134, 'Marcos de análisis de negocios', 'Rol del analista de negocios', 'Intermedia', '¿Cuál es una diferencia típica entre el analista de negocios y el director del proyecto?', 'El analista aprueba el presupuesto; el director, los requisitos.', 'El analista se centra en el producto y sus requisitos; el director, en la entrega del proyecto.', 'No hay diferencias: ambos roles hacen exactamente lo mismo.', 'El analista dirige al equipo; el director documenta los requisitos.', 'B', 'Son roles complementarios: el producto (qué) y el proyecto (cómo se entrega).'),
(135, 'Marcos de análisis de negocios', 'Evaluación de necesidades', 'Básica', '¿Qué documento justifica una inversión analizando beneficios, costos, opciones y riesgos antes de iniciar el proyecto?', 'La matriz RACI.', 'El diccionario de la EDT.', 'El caso de negocio.', 'El acta de constitución.', 'C', 'El caso de negocio justifica económicamente el proyecto.'),
(136, 'Marcos de análisis de negocios', 'Evaluación de necesidades', 'Intermedia', '¿Qué describe el plan de gestión de beneficios?', 'Los proveedores y sus contratos.', 'La secuencia de actividades del cronograma.', 'Cómo y cuándo se entregarán los beneficios del proyecto y cómo se medirán.', 'Los beneficios salariales del equipo.', 'C', 'Este plan asegura que el proyecto genere el valor esperado.'),
(137, 'Marcos de análisis de negocios', 'Evaluación de necesidades', 'Intermedia', 'El analista compara la situación actual de la organización con la situación futura deseada para identificar qué falta. ¿Qué técnica usa?', 'Análisis de Pareto.', 'Análisis del valor ganado.', 'Análisis de sensibilidad.', 'Análisis de brechas (gap analysis).', 'D', 'El análisis de brechas identifica la diferencia entre el estado actual y el deseado.'),
(138, 'Marcos de análisis de negocios', 'Tipos de requisitos', 'Intermedia', '"Aumentar las ventas en línea un 15 % en el próximo año" es un ejemplo de:', 'Requisito de negocio.', 'Requisito no funcional.', 'Requisito funcional.', 'Requisito de transición.', 'A', 'Los requisitos de negocio describen las necesidades de alto nivel de la organización.'),
(139, 'Marcos de análisis de negocios', 'Tipos de requisitos', 'Intermedia', '"El sistema debe responder a cualquier consulta en menos de 2 segundos" es un ejemplo de:', 'Requisito funcional.', 'Requisito no funcional.', 'Regla de negocio.', 'Requisito de negocio.', 'B', 'Los requisitos no funcionales describen atributos de calidad como el rendimiento o la seguridad.'),
(140, 'Marcos de análisis de negocios', 'Tipos de requisitos', 'Básica', '"El sistema debe permitir al usuario generar facturas electrónicas" es un ejemplo de:', 'Requisito de transición.', 'Requisito no funcional.', 'Requisito funcional.', 'Requisito de negocio.', 'C', 'Los requisitos funcionales describen comportamientos o funciones del producto.'),
(141, 'Marcos de análisis de negocios', 'Tipos de requisitos', 'Intermedia', 'La migración de datos del sistema antiguo y la capacitación de los usuarios son ejemplos de requisitos:', 'De negocio.', 'Funcionales.', 'De transición.', 'De calidad.', 'C', 'Los requisitos de transición son temporales y permiten pasar del estado actual al futuro.'),
(142, 'Marcos de análisis de negocios', 'Tipos de requisitos', 'Intermedia', '"Los clientes con más de 5 años de antigüedad reciben un 10 % de descuento" es un ejemplo de:', 'Requisito de transición.', 'Regla de negocio.', 'Supuesto.', 'Requisito no funcional.', 'B', 'Las reglas de negocio son políticas o condiciones que guían el negocio.'),
(143, 'Marcos de análisis de negocios', 'Trazabilidad', 'Intermedia', '¿Qué herramienta vincula cada requisito con su origen y con los entregables que lo satisfacen?', 'La matriz RACI.', 'La matriz de poder/interés.', 'La matriz de trazabilidad de requisitos.', 'La matriz de probabilidad e impacto.', 'C', 'La trazabilidad sigue cada requisito a lo largo de su ciclo de vida.'),
(144, 'Marcos de análisis de negocios', 'Trazabilidad', 'Avanzada', 'Un interesado propone un requisito nuevo que no se puede vincular con ningún objetivo de negocio. Según la trazabilidad, ¿qué debe hacer el analista?', 'Incluirlo de inmediato porque lo pidió un interesado.', 'Añadirlo directamente en la línea base sin análisis.', 'Cuestionar su valor y analizarlo con los interesados antes de incluirlo.', 'Eliminar el objetivo de negocio para incluir el requisito.', 'C', 'Todo requisito debe estar vinculado a un objetivo de negocio que justifique su valor.'),
(145, 'Marcos de análisis de negocios', 'Elicitación', 'Básica', '¿Qué técnica de elicitación obtiene información detallada mediante conversaciones directas, una a una, con los interesados?', 'Benchmarking.', 'Encuestas.', 'Análisis de documentos.', 'Entrevistas.', 'D', 'Las entrevistas permiten profundizar con cada interesado.'),
(146, 'Marcos de análisis de negocios', 'Elicitación', 'Intermedia', 'El analista reúne a un grupo de usuarios preseleccionados con un moderador para conocer sus expectativas sobre un producto. ¿Qué técnica usa?', 'Observación.', 'Entrevista individual.', 'Análisis de interfaces.', 'Grupo focal (focus group).', 'D', 'El grupo focal reúne a participantes preseleccionados guiados por un moderador.'),
(147, 'Marcos de análisis de negocios', 'Elicitación', 'Intermedia', 'Varios interesados de distintas áreas se reúnen en una sesión estructurada y facilitada para definir requisitos y resolver diferencias. ¿Qué técnica es?', 'Taller facilitado (por ejemplo, JAD).', 'Observación pasiva.', 'Análisis de documentos.', 'Encuesta.', 'A', 'Los talleres facilitados integran a las distintas áreas y ayudan a llegar a acuerdos rápidamente.'),
(148, 'Marcos de análisis de negocios', 'Elicitación', 'Intermedia', 'A los usuarios les cuesta explicar cómo hacen su trabajo. ¿Qué técnica de elicitación es la más adecuada?', 'Observación (shadowing).', 'Encuesta.', 'Benchmarking.', 'Análisis de documentos.', 'A', 'Observar el trabajo directamente revela procesos difíciles de explicar.'),
(149, 'Marcos de análisis de negocios', 'Elicitación', 'Básica', 'Se necesita información de cientos de usuarios distribuidos en varias ciudades en poco tiempo. ¿Qué técnica es la más adecuada?', 'Talleres presenciales.', 'Entrevistas individuales.', 'Observación directa.', 'Cuestionarios y encuestas.', 'D', 'Las encuestas permiten llegar a muchas personas rápidamente.'),
(150, 'Marcos de análisis de negocios', 'Elicitación', 'Intermedia', 'El analista crea un modelo preliminar del producto para que los usuarios interactúen con él y den retroalimentación temprana. ¿Qué técnica usa?', 'Análisis FODA.', 'Prototipos.', 'Análisis de documentos.', 'Encuestas.', 'B', 'Los prototipos hacen tangibles los requisitos antes de construir el producto.'),
(151, 'Marcos de análisis de negocios', 'Elicitación', 'Básica', 'El analista revisa manuales, contratos y procedimientos existentes para identificar requisitos. ¿Qué técnica usa?', 'Análisis de documentos.', 'Lluvia de ideas.', 'Grupo focal.', 'Prototipos.', 'A', 'El análisis de documentos aprovecha la información que ya existe.'),
(152, 'Marcos de análisis de negocios', 'Elicitación', 'Básica', '¿Qué técnica grupal busca generar muchas ideas en poco tiempo sin criticarlas al principio?', 'Técnica de grupo nominal.', 'Lluvia de ideas.', 'Análisis de decisiones.', 'Votación por mayoría.', 'B', 'En la lluvia de ideas primero se generan ideas y después se evalúan.'),
(153, 'Marcos de análisis de negocios', 'Priorización', 'Básica', 'En la técnica de priorización MoSCoW, ¿qué significa la "M"?', 'Podría tenerse (Could have).', 'Debe tenerse (Must have).', 'No se tendrá esta vez (Won''t have).', 'Debería tenerse (Should have).', 'B', 'Must, Should, Could y Won''t.'),
(154, 'Marcos de análisis de negocios', 'Priorización', 'Intermedia', 'En MoSCoW, un requisito importante pero no indispensable para la entrega actual se clasifica como:', 'Debería tenerse (Should have).', 'Podría tenerse (Could have).', 'Debe tenerse (Must have).', 'No se tendrá (Won''t have).', 'A', 'Should: importante, pero la solución funciona sin él.'),
(155, 'Marcos de análisis de negocios', 'Priorización', 'Avanzada', 'Según el modelo de Kano, ¿cómo se llaman las características que el cliente no espera pero que, si están, generan gran satisfacción?', 'Características de desempeño.', 'Características básicas (obligatorias).', 'Características de deleite (atractivas).', 'Características indiferentes.', 'C', 'Las características de deleite sorprenden y generan satisfacción, y su ausencia no molesta.'),
(156, 'Marcos de análisis de negocios', 'Priorización', 'Intermedia', 'Cada interesado reparte 100 puntos entre los requisitos según su importancia. ¿Qué técnica de priorización es?', 'Matriz RACI.', 'Análisis de Pareto.', 'Asignación de 100 puntos.', 'MoSCoW.', 'C', 'La asignación de 100 puntos obliga a decidir cuánto pesa cada requisito.'),
(157, 'Marcos de análisis de negocios', 'Análisis situacional', 'Básica', 'En un análisis FODA, ¿qué representan las debilidades?', 'Factores externos positivos del mercado.', 'Factores externos negativos del entorno.', 'Factores internos que dan ventaja competitiva.', 'Factores internos que limitan a la organización.', 'D', 'Fortalezas y debilidades son internas; oportunidades y amenazas son externas.'),
(158, 'Marcos de análisis de negocios', 'Análisis situacional', 'Intermedia', '¿Qué técnica analiza los factores políticos, económicos, sociales, tecnológicos, legales y ambientales del entorno?', 'Análisis de causa raíz.', 'Análisis PESTLE.', 'Análisis de interesados.', 'Análisis FODA.', 'B', 'PESTLE estudia los factores del entorno externo.'),
(159, 'Marcos de análisis de negocios', 'Modelado', 'Intermedia', '¿Qué modelo muestra el sistema como un todo, las entidades externas que interactúan con él y las interfaces entre ellos?', 'Diagrama de Ishikawa.', 'Diagrama de contexto.', 'Mapa de historias.', 'Diagrama de Gantt.', 'B', 'El diagrama de contexto delimita el alcance del sistema y sus interfaces.'),
(160, 'Marcos de análisis de negocios', 'Modelado', 'Intermedia', '¿Qué diagrama muestra cómo interactúan los actores con el sistema para lograr sus objetivos?', 'Diagrama de casos de uso.', 'Organigrama.', 'Diagrama de red del cronograma.', 'Histograma.', 'A', 'Los casos de uso describen las interacciones entre los actores y el sistema.'),
(161, 'Marcos de análisis de negocios', 'Modelado', 'Básica', '¿Qué modelo representa paso a paso las actividades, decisiones y responsables de un proceso de negocio?', 'Diagrama de flujo del proceso.', 'Diagrama entidad-relación.', 'Matriz de trazabilidad.', 'Diagrama de dispersión.', 'A', 'Los flujos de proceso muestran la secuencia de actividades y decisiones.'),
(162, 'Marcos de análisis de negocios', 'Modelado', 'Intermedia', 'El analista documenta cómo funciona hoy un proceso y luego diseña cómo debería funcionar después de la solución. ¿Cómo se llaman estos modelos?', 'Plan maestro y plan detallado.', 'Modelo del estado actual (AS-IS) y modelo del estado futuro (TO-BE).', 'Riesgo inherente y riesgo residual.', 'Línea base y pronóstico.', 'B', 'AS-IS describe la situación actual y TO-BE la deseada.'),
(163, 'Marcos de análisis de negocios', 'Modelado', 'Avanzada', 'Una regla de negocio depende de varias combinaciones de condiciones (tipo de cliente, monto y forma de pago). ¿Qué modelo es el más adecuado para representarla?', 'Una tabla de decisión.', 'Un diagrama de contexto.', 'Un diagrama de Gantt.', 'Un organigrama.', 'A', 'Las tablas de decisión muestran de forma clara las combinaciones de condiciones y sus resultados.'),
(164, 'Marcos de análisis de negocios', 'Modelado', 'Intermedia', '¿Qué modelo muestra las entidades de información y las relaciones entre ellas?', 'Diagrama de flujo acumulado.', 'Diagrama entidad-relación (ER).', 'Diagrama de Pareto.', 'Diagrama de casos de uso.', 'B', 'El diagrama ER modela los datos y sus relaciones.'),
(165, 'Marcos de análisis de negocios', 'Modelado', 'Básica', '¿Qué representación visual de baja fidelidad muestra la estructura de una pantalla sin diseño gráfico detallado?', 'Un wireframe.', 'Un diagrama de red.', 'Un diagrama de Ishikawa.', 'Un histograma.', 'A', 'El wireframe sirve para validar la estructura de la interfaz antes de diseñarla.'),
(166, 'Marcos de análisis de negocios', 'Análisis de decisiones', 'Avanzada', 'Construir cuesta $100 000 y genera $300 000 con demanda alta (70 %) o $120 000 con demanda baja (30 %). Comprar cuesta $50 000 y genera $200 000 (70 %) o $100 000 (30 %). Según el valor monetario esperado neto, ¿qué conviene?', 'Construir, con un VME neto de $210 000.', 'Comprar, con un VME neto de $170 000.', 'Construir, con un VME neto de $146 000.', 'Comprar, con un VME neto de $120 000.', 'C', 'Construir: 0,7×300 + 0,3×120 − 100 = 146. Comprar: 0,7×200 + 0,3×100 − 50 = 120.'),
(167, 'Marcos de análisis de negocios', 'Análisis financiero', 'Intermedia', 'El proyecto A tiene un VAN de $120 000 en 5 años y el proyecto B tiene un VAN de $100 000 en 2 años. Si solo se puede elegir uno, ¿cuál conviene según el VAN?', 'El proyecto B, porque dura menos.', 'El proyecto A, porque tiene el VAN más alto.', 'Ninguno: el VAN no sirve para comparar proyectos.', 'El proyecto B, porque el VAN debe dividirse entre los años.', 'B', 'El VAN ya considera el valor del dinero en el tiempo, así que se elige el mayor.'),
(168, 'Marcos de análisis de negocios', 'Análisis financiero', 'Intermedia', 'Una inversión de $60 000 genera un flujo neto de $15 000 por año. ¿Cuál es su período de recuperación?', '4 años.', '3 años.', '5 años.', '6 años.', 'A', '60 000 / 15 000 = 4 años.'),
(169, 'Marcos de análisis de negocios', 'Análisis financiero', 'Básica', 'Si se comparan proyectos solo por su tasa interna de retorno (TIR), ¿cuál se prefiere?', 'El que tenga la TIR igual a cero.', 'El que tenga la TIR más baja.', 'El que tenga la TIR más alta.', 'La TIR no se usa para seleccionar proyectos.', 'C', 'Una TIR mayor indica una rentabilidad mayor.'),
(170, 'Marcos de análisis de negocios', 'Análisis financiero', 'Avanzada', 'Una empresa elige el proyecto A (VAN de $80 000) en lugar del proyecto B (VAN de $50 000). ¿Cuál es el costo de oportunidad?', '$30 000.', '$130 000.', '$80 000.', '$50 000.', 'D', 'El costo de oportunidad es el valor de la mejor alternativa a la que se renuncia.'),
(171, 'Marcos de análisis de negocios', 'Alcance del producto', 'Intermedia', '¿Qué es el alcance del producto?', 'La lista de miembros del equipo.', 'El trabajo necesario para entregar el producto.', 'Las características y funciones que describen al producto, servicio o resultado.', 'El presupuesto asignado al producto.', 'C', 'El alcance del producto se mide contra los requisitos; el alcance del proyecto, contra el plan.'),
(172, 'Marcos de análisis de negocios', 'Hoja de ruta', 'Intermedia', '¿Qué herramienta muestra a alto nivel cómo evolucionará el producto a lo largo del tiempo y en qué versiones se entregarán las capacidades?', 'El diccionario de la EDT.', 'El registro de riesgos.', 'El acta de constitución.', 'La hoja de ruta del producto (product roadmap).', 'D', 'La hoja de ruta comunica la visión y la secuencia de las entregas del producto.'),
(173, 'Marcos de análisis de negocios', 'Evaluación de la solución', 'Intermedia', 'Seis meses después de implementar un sistema, el analista mide si se lograron los beneficios esperados. ¿Qué actividad realiza?', 'Elicitar los requisitos.', 'Evaluar la solución.', 'Definir el acta de constitución.', 'Crear la EDT.', 'B', 'La evaluación de la solución verifica si se entregó el valor esperado.'),
(174, 'Marcos de análisis de negocios', 'Gestión de requisitos', 'Intermedia', 'Después de aprobada la línea base de requisitos, un interesado pide modificar un requisito. ¿Qué debe hacer el analista?', 'Cambiar el requisito directamente en la documentación.', 'Analizar el impacto y gestionar el cambio según el proceso de control de cambios.', 'Rechazar cualquier cambio después de aprobada la línea base.', 'Esperar al cierre del proyecto para evaluarlo.', 'B', 'Los cambios en requisitos aprobados se controlan formalmente.'),
(175, 'Marcos de análisis de negocios', 'Gestión de requisitos', 'Avanzada', 'Un requisito dice "El sistema debe ser rápido y fácil de usar". ¿Cuál es la mejor acción del analista?', 'Eliminarlo porque es subjetivo.', 'Dejar que los desarrolladores lo interpreten.', 'Aclararlo con los interesados y convertirlo en criterios medibles y verificables.', 'Aceptarlo tal como está.', 'C', 'Los requisitos deben ser claros, medibles y verificables.'),
(176, 'Marcos de análisis de negocios', 'Análisis de interesados', 'Intermedia', 'El analista crea un perfil ficticio que representa a un grupo de usuarios típicos, con sus objetivos y frustraciones. ¿Qué técnica usa?', 'Diagrama de contexto.', 'Persona (user persona).', 'Organigrama.', 'Matriz RACI.', 'B', 'Las personas ayudan a diseñar pensando en usuarios representativos.'),
(177, 'Marcos de análisis de negocios', 'Viabilidad', 'Intermedia', 'Antes de aprobar una iniciativa, se analiza si es técnica, económica y operativamente posible. ¿Qué estudio es?', 'Auditoría de calidad.', 'Revisión del sprint.', 'Retrospectiva.', 'Estudio de viabilidad (factibilidad).', 'D', 'El estudio de viabilidad evalúa si la solución es posible y conveniente.'),
(178, 'Marcos de análisis de negocios', 'Métricas', 'Intermedia', '¿Cuál de los siguientes es un indicador de éxito bien definido para una solución?', 'Reducir el tiempo promedio de atención de 10 a 6 minutos en 6 meses.', 'Hacer que el sistema sea mejor.', 'Mejorar la atención al cliente.', 'Lograr que los usuarios estén contentos.', 'A', 'Un buen indicador es específico, medible y tiene un plazo (SMART).'),
(179, 'Marcos de análisis de negocios', 'Análisis de negocios en entornos ágiles', 'Intermedia', 'En un entorno ágil, ¿cómo suele colaborar el analista de negocios?', 'Aprueba el presupuesto de cada sprint.', 'Trabaja con el Product Owner para refinar el backlog y aclarar las historias de usuario.', 'Escribe todos los requisitos al inicio y deja el proyecto.', 'Reemplaza al Scrum Master en los eventos.', 'B', 'En ágil, el analista ayuda al Product Owner a mantener un backlog claro y valioso.'),
(180, 'Marcos de análisis de negocios', 'Análisis de causa raíz', 'Intermedia', 'Antes de proponer una solución, el analista quiere asegurarse de atacar el problema real y no sus síntomas. ¿Qué debe hacer?', 'Implementar la solución que pidió el interesado de mayor jerarquía.', 'Redactar de inmediato los requisitos técnicos.', 'Realizar un análisis de causa raíz del problema.', 'Comprar el software más popular del mercado.', 'C', 'Entender la causa raíz evita invertir en soluciones que no resuelven la necesidad.')
